import sys
from collections import defaultdict

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))

    adj = defaultdict(list)
    parent = {}
    char_to_parent = {}

    for _ in range(n - 1):
        u = int(next(iterator))
        v = int(next(iterator))
        c = next(iterator)
        adj[u].append((v, c))
        parent[v] = u
        char_to_parent[(u, c)] = v

    depths = [0] * (n + 1)
    queue = [1]
    visited = {1}
    order = []

    while queue:
        u = queue.pop(0)
        order.append(u)
        for v, c in adj[u]:
            if v not in visited:
                visited.add(v)
                depths[v] = depths[u] + 1
                queue.append(v)

    max_depth = max(depths[1:])

    suffix_counts = [0] * (max_depth + 2)

    for u in order:
        d = depths[u]
        if d > 0:
            suffix_counts[d] += 1

    suffix_sum = [0] * (max_depth + 2)
    for i in range(max_depth, 0, -1):
        suffix_sum[i] = suffix_sum[i+1] + suffix_counts[i]

    total_words = suffix_sum[1]

    best_size = n
    best_p = 1

    for p in range(1, max_depth + 1):
        if suffix_sum[p] == 0:
            break

        removed = 0
        for k in range(p, max_depth + 1):
            removed += suffix_counts[k]

        current_size = n - removed
        if current_size < best_size:
            best_size = current_size
            best_p = p
        elif current_size == best_size:
            if p < best_p:
                best_p = p

    print(best_size)
    print(best_p)

if __name__ == "__main__":
    main()
